  P.push([/^(\d+) h ago$/, function (m) { return 'قبل ' + m[1] + ' س'; }]);
  P.push([/^(\d+) KPIs? measured$/, function (m) { return m[1] + ' مؤشرات مقيسة'; }]);
  P.push([/^(\d+) time\(s\)$/, function (m) { return m[1] + ' مرة'; }]);
  P.push([/^(\d+) (critical|high|medium|low)$/, function (m, tr) { return m[1] + ' ' + tr(m[2]); }]);
  P.push([/^Open: (P-\d\d)$/, function (m) { return 'مفتوح: ' + m[1]; }]);
  P.push([/^Open: other$/, function () { return 'مفتوح: أخرى'; }]);
  P.push([/^\((high|medium|low)\)$/, function (m, tr) { var t = tr(m[1]); return t === m[1] ? null : '(' + t + ')'; }]);
  P.push([/^Fix: (.+)$/, function (m, tr) { var t = tr(m[1]); return t === m[1] ? null : 'الحل: ' + t; }]);
  P.push([/^(non_compliant|partial|auto_pass|manual): the registers show a gap: (.+)$/, function (m, tr) { var t = tr(m[2]); return t === m[2] ? null : (m[1] === 'non_compliant' ? 'غير ممتثل' : tr(m[1])) + ': تُظهر السجلات ثغرة: ' + t; }]);
  P.push([/^(P-\d\d) (.+) \((.+)\) - owned by Governance, Risk & Compliance with the DPO\.$/, function (m, tr) { var t = tr(m[2]); return t === m[2] ? null : m[1] + ' ' + t + ' (' + tr(m[3]) + ') - تملكه إدارة الحوكمة والمخاطر والالتزام مع مسؤول حماية البيانات.'; }]);
  P = P.map(function (x) { return [x[0], function (m, tr) { var r = x[1](m, tr); if (r == null) throw new Error('no translation'); return r; }]; });
  // whole paragraphs: key = the paragraph's own text (block children such as step chips are left in place)
  var B = {
    'PDPL compliance is a business capability, not a legal checkbox: legal interprets, governance sets standards and ownership, IT builds the controls, marketing handles opt-ins and product builds privacy in by design. Each department names a data steward - the bridge between the compliance goals and its day-to-day work - and keeps short team playbooks. The obligations below are a controller\'s duties under the law and its Implementing Regulation, each with what the registers show and the penalty it carries. The maturity assessment scores four areas: data mapping and ownership, consent, team responsibilities and training, documentation and audit readiness.':
      'الالتزام لنظام حماية البيانات قدرة مؤسسية لا خانة قانونية: الشؤون القانونية تفسّر، والحوكمة تضع المعايير والملكية، وتقنية المعلومات تبني الضوابط، والتسويق يتولى الموافقات، وفريق المنتجات يدمج الخصوصية بالتصميم. تسمّي كل إدارة <b>مسؤول بيانات</b> - حلقة الوصل بين أهداف الالتزام وعملها اليومي - وتحتفظ بـ<b>أدلة عمل</b> مختصرة. الالتزامات أدناه واجبات جهة التحكم وفق النظام ولائحته التنفيذية، ولكل منها ما تُظهره السجلات والعقوبة المترتبة. ويقيس تقييم النضج أربعة مجالات: حصر البيانات وملكيتها، والموافقة، ومسؤوليات الفرق والتدريب، والتوثيق والجاهزية للتدقيق.',
    'A PDPL programme needs clear decision-making authority, not only policy documents: a DPO with direct access to executive management and the authority to stop risky processing; a named person (not a job title) for each function; a data protection committee of legal, IT, HR and operations meeting at least quarterly; a privacy review before any new system or product goes live; and a yearly programme review whose findings become actions with an owner and a due date, closed with evidence.':
      'يحتاج برنامج حماية البيانات صلاحية قرار واضحة لا وثائق سياسات فقط: مسؤول حماية بيانات يصل مباشرة إلى الإدارة التنفيذية وله صلاحية إيقاف المعالجة الخطرة؛ و<b>شخص مسمّى</b> (لا مسمى وظيفي) لكل وظيفة؛ و<b>لجنة حماية بيانات</b> من الشؤون القانونية وتقنية المعلومات والموارد البشرية والعمليات تجتمع كل ربع سنة على الأقل؛ و<b>مراجعة خصوصية قبل تشغيل أي نظام أو منتج جديد</b>؛ و<b>مراجعة سنوية للبرنامج</b> تتحول ملاحظاتها إلى إجراءات لها مالك وموعد، وتُغلق بدليل.',
    'The consultant oversees compliance with the Personal Data Protection Law: it checks the registers against 24 requirements, raises every gap as work for Governance, and prepares the compliance statement. It changes nothing and signs nothing. The statement is signed by the appointed DPO and countersigned by a different person in management. It is an internal self-assessment, not an SDAIA certificate: only SDAIA, or a body it accredits, can certify.':
      'يشرف المستشار على الالتزام لنظام حماية البيانات الشخصية: يفحص السجلات مقابل 24 متطلباً، ويرفع كل ثغرة عملاً للحوكمة، ويُعدّ <b>إقرار الالتزام</b>. لا يغيّر شيئاً ولا يوقّع شيئاً. يوقّع الإقرار مسؤول حماية البيانات المعيَّن ويصادق عليه <b>شخص آخر من الإدارة</b>. وهو تقييم ذاتي داخلي، <b>وليس شهادة من سدايا</b>: لا يمنح الشهادة إلا سدايا أو جهة تعتمدها.',
    'This engineer patrols on its own, opens a work item for each problem, investigates it read-only and proposes the fix. It never changes anything itself: change plans are approved by an administrator (never the one who asked) and applied by a person, then the engineer re-checks. Roles & approvals →':
      'يتجول هذا المهندس من تلقاء نفسه، ويفتح بند عمل لكل مشكلة، ويحقق فيها بالقراءة فقط ويقترح الحل. لا يغيّر شيئاً بنفسه: خطط التغيير يعتمدها مسؤول منصة (ليس من طلبها) وينفّذها شخص، ثم يعيد المهندس الفحص. <a href="ai-engineers.html">الأدوار والموافقات ←</a>',
    ['The policies and procedures PDPL expects ' + ZYB_ORG.short + ' to have, checked against the approved IT policy register and the GRC drafts. For each: whether it is approved, in review, a draft or missing, what it must cover (drawn from the law and its regulations - an outline, not policy text), the page that runs it day to day and what the registers show. Start a draft creates it on GRC Policies & Controls with that outline; it is written there and approved by an administrator who did not write it.']:
      ('السياسات والإجراءات التي يتوقع النظام وجودها لدى ' + ZYB_ORG.short_ar + '، مقارنةً بسجل سياسات تقنية المعلومات المعتمدة ومسودات الحوكمة. لكل منها: هل هي معتمدة أو قيد المراجعة أو مسودة أو ناقصة، وما يجب أن تغطيه (مستمد من النظام ولوائحه - مخطط لا نص سياسة)، والصفحة التي تديرها يومياً، وما تُظهره السجلات. زر <b>بدء مسودة</b> ينشئها في سياسات وضوابط الحوكمة بهذا المخطط؛ وتُكتب هناك ويعتمدها مسؤول منصة لم يكتبها.'),
    'Every Oracle, SQL Server and PostgreSQL database with a proven read-only login is scanned; SharePoint / OneDrive is read through Microsoft Graph and file shares by the Windows agent on the file server. For databases: column names, comments and row estimates from the dictionary; where the login may read a table, 50 values are tested on the platform server and only the number of matches is kept. No personal data value is stored or shown. An administrator confirms the identifier columns a person can be found by; the search itself runs from a verified data subject request.':
      'تُفحص كل قاعدة بيانات Oracle وSQL Server وPostgreSQL لها دخول مثبت للقراءة فقط؛ ويُقرأ SharePoint / OneDrive عبر Microsoft Graph، ومجلدات المشاركة عبر وكيل Windows على خادم الملفات. لقواعد البيانات: أسماء الأعمدة وتعليقاتها وتقديرات الصفوف من القاموس؛ وحيث يُسمح بقراءة الجدول تُختبر 50 قيمة على خادم المنصة ولا يُحفظ إلا عدد المطابقات. <b>لا تُحفظ ولا تُعرض أي قيمة من البيانات الشخصية.</b> يؤكد مسؤول المنصة أعمدة المعرِّفات التي يُبحث بها عن الشخص؛ ويجري البحث نفسه من طلب صاحب بيانات تم التحقق منه.',
    'Only the request reference is kept here: the person\'s name and details stay in the customer systems. The answer is due in 30 days; once, with notice and reasons before the 30 days end, it may be extended by 30 days. Identity is verified first, every system that holds the person\'s data is worked, and the answer letter (Arabic and English) is drafted from the request.':
      '<b>يُحفظ هنا رقم الطلب فقط</b>: يبقى اسم الشخص وبياناته في أنظمة العملاء. تُستحق الإجابة خلال 30 يوماً؛ ويجوز تمديدها مرة واحدة 30 يوماً بإشعار وأسباب قبل انتهاء الثلاثين يوماً. يُتحقق من الهوية أولاً، ويُعالج كل نظام يحتوي بيانات الشخص، ويُصاغ خطاب الإجابة (بالعربية والإنجليزية) من الطلب.',
    'Requests from customers and employees to access, copy, correct or destroy their personal data, withdraw consent or object. Staff record each request here when it arrives (branch, call centre, e-mail, web, letter). Only the request reference is kept here: the person\'s name and details stay in the customer systems. The answer is due in 30 days; once, with notice and reasons before the 30 days end, it may be extended by 30 days. Identity is verified first, every system that holds the person\'s data is worked, and the answer letter (Arabic and English) is drafted from the request.':
      'طلبات العملاء والموظفين للوصول إلى بياناتهم الشخصية أو نسخها أو تصحيحها أو إتلافها أو سحب الموافقة أو الاعتراض. يسجّل الموظفون كل طلب هنا عند وصوله (الفرع، مركز الاتصال، البريد، الموقع، الخطاب). <b>يُحفظ هنا رقم الطلب فقط</b>: يبقى اسم الشخص وبياناته في أنظمة العملاء. تُستحق الإجابة خلال 30 يوماً؛ ويجوز تمديدها مرة واحدة 30 يوماً بإشعار وأسباب قبل انتهاء الثلاثين يوماً. يُتحقق من الهوية أولاً، ويُعالج كل نظام يحتوي بيانات الشخص، ويُصاغ خطاب الإجابة (بالعربية والإنجليزية) من الطلب.',
    'An impact assessment is required before processing sensitive data, combining data from two or more sources, continuous monitoring, solely automated decisions, or anything else likely to harm a person\'s privacy (PDPL Art. 22; Implementing Regulation Art. 25). The questionnaire is scored in Python (likelihood + severity, each measure reduces it, every point named). The result is a draft until the DPO signs it, and the DPO cannot sign an assessment they prepared. Re-assess when the activity changes, at least every 2 years.':
      'يلزم تقييم الأثر قبل معالجة البيانات الحساسة، أو دمج بيانات من مصدرين أو أكثر، أو المراقبة المستمرة، أو القرارات الآلية بالكامل، أو أي معالجة يُحتمل أن تضر بخصوصية الشخص (المادة 22 من النظام؛ المادة 25 من اللائحة التنفيذية). يُحتسب الاستبيان آلياً (الاحتمال + الشدة، وكل إجراء يخفضها، وكل نقطة مسمّاة). تبقى النتيجة مسودة حتى <b>يوقّعها مسؤول حماية البيانات</b>، ولا يوقّع تقييماً أعدّه بنفسه. أعِد التقييم عند تغيّر النشاط، ومرة كل سنتين على الأقل.',
    'Personal data leaves the Kingdom only for a permitted purpose (PDPL Art. 29) and on a basis: an SDAIA adequacy decision, appropriate safeguards (standard contractual clauses, binding common rules, certification, code of conduct) or an exemption. Safeguards, exemptions and continuous or large-scale sensitive transfers need a transfer impact assessment first (Cross-Border Transfer Regulation Art. 8): purpose, scope, safeguards, minimisation, impact on people and the measures that reduce it. A transfer must stop at once if the assessment shows high risk or the safeguards no longer hold. The assessment is scored in Python and signed by the DPO, who did not prepare it.':
      'لا تخرج البيانات الشخصية من المملكة إلا لغرض مسموح (المادة 29 من النظام) وعلى أساس: قرار ملاءمة من سدايا، أو ضمانات مناسبة (بنود تعاقدية معيارية، قواعد مشتركة ملزمة، شهادة، مدونة سلوك)، أو استثناء. وتحتاج الضمانات والاستثناءات والنقل المستمر أو واسع النطاق للبيانات الحساسة <b>تقييم أثر النقل</b> أولاً (لائحة نقل البيانات، المادة 8): الغرض والنطاق والضمانات وتقليل البيانات والأثر على الأشخاص والإجراءات التي تخففه. ويجب إيقاف النقل فوراً إن أظهر التقييم مخاطر عالية أو لم تعد الضمانات قائمة. يُحتسب التقييم آلياً ويوقّعه مسؤول حماية البيانات الذي لم يُعدّه.',
    'From the moment a person decides an incident affects personal data, SDAIA must be told within 72 hours, and the people affected without undue delay when harm is likely (Implementing Regulation Art. 24). Each breach follows the playbook: contain, assess (what data, how many people, sensitive?, likely harm), notify SDAIA, notify the data subjects, remediate, lessons learned. Every step is stamped with who and when. The platform prepares the SDAIA notification and the data-subject notice; the DPO files them in SDAIA\'s portal - nothing is sent from here. Each breach also carries a decision for the other regulators (Insurance Authority, SAMA, NCA, Council of Health Insurance): required or not, and when and under which reference each was told.':
      'من لحظة تقرير شخص أن الحادثة تمس بيانات شخصية، <b>يجب إبلاغ سدايا خلال 72 ساعة</b>، وإبلاغ المتأثرين دون تأخير غير مبرر عند احتمال الضرر (اللائحة التنفيذية، المادة 24). تتبع كل حادثة دليل الاستجابة: الاحتواء، التقييم (أي بيانات، كم شخصاً، حساسة؟، الضرر المحتمل)، إبلاغ سدايا، إبلاغ أصحاب البيانات، المعالجة، الدروس المستفادة. تُختم كل خطوة بمن نفّذها ومتى. تُعدّ المنصة إشعار سدايا وإشعار أصحاب البيانات؛ ويرفعهما مسؤول حماية البيانات في بوابة سدايا - لا يُرسل شيء من هنا. ولكل حادثة قرار بشأن الجهات الرقابية الأخرى (هيئة التأمين، ساما، الهيئة الوطنية للأمن السيبراني، مجلس الضمان الصحي): مطلوب أم لا، ومتى أُبلغت كل جهة وبأي مرجع.',
    'The claims, medical-review and fraud systems send who opened which record and why. Policies flag sensitive records opened with no purpose, investigations with no case reference, sensitive exports and deletions; volume indicators compare each person with their own usual day. Health data needs tiered access with every stage documented (PDPL Art. 23, Implementing Regulation Art. 26). Behavioural indicators, not proof of wrongdoing - a reviewer who is not the person concerned records justified or escalated.':
      'ترسل أنظمة المطالبات والمراجعة الطبية والاحتيال من فتح أي سجل ولماذا. تنبّه السياسات إلى السجلات الحساسة المفتوحة دون غرض، والتحقيقات دون رقم قضية، وتصدير السجلات الحساسة وحذفها؛ وتقارن مؤشرات الحجم كل شخص بيومه المعتاد. تحتاج البيانات الصحية وصولاً متدرّجاً مع توثيق كل مرحلة (المادة 23 من النظام، المادة 26 من اللائحة التنفيذية). <b>مؤشرات سلوكية، وليست دليلاً على مخالفة</b> - يسجّل مراجِع غير الشخص المعني «مبرَّر» أو «مُصعَّد».',
    ['Every party that processes personal data for ' + ZYB_ORG.short + ' (TPAs, reinsurers, call centres, cloud and IT services, printing, collection agencies) works only on written instructions and must give sufficient guarantees. The agreement carries the PDPL terms; the processor is assessed periodically (here: every 12 months, due-diligence questionnaire scored in Python); each sub-processor is approved in advance by the DPO or an administrator who did not propose it. A processor that breaks the agreement becomes a controller and is liable itself (PDPL Art. 8; Implementing Regulation Art. 17).']:
      ('كل جهة تعالج بيانات شخصية لصالح ' + ZYB_ORG.short_ar + ' (مديرو المطالبات، معيدو التأمين، مراكز الاتصال، الخدمات السحابية وخدمات تقنية المعلومات، الطباعة، التحصيل) تعمل وفق تعليمات مكتوبة فقط وعليها تقديم ضمانات كافية. تتضمن الاتفاقية بنود النظام؛ ويُقيَّم المعالج دورياً (هنا: كل 12 شهراً، باستبيان عناية واجبة يُحتسب آلياً)؛ و<b>كل معالج من الباطن يُعتمد مسبقاً</b> من مسؤول حماية البيانات أو مسؤول منصة لم يقترحه. والمعالج الذي يخالف الاتفاقية يصبح جهة تحكم ومسؤولاً بنفسه (المادة 8 من النظام؛ المادة 17 من اللائحة التنفيذية).'),
    'Stewards and champions are named on the Programme page, function owners on Governance, the DPO in the PDPL profile; the committee, deputy DPO and data owners in Settings.':
      'يُسمّى مسؤولو البيانات وسفراء الخصوصية في صفحة <a href="pdpl-programme.html">البرنامج</a>، ومالكو الوظائف في <a href="pdpl-governance.html">الحوكمة</a>، ومسؤول حماية البيانات في ملف حماية البيانات؛ واللجنة ونائب مسؤول حماية البيانات ومالكو البيانات في الإعدادات.'
  };
  var INLINE = /^(B|STRONG|A|I|EM|SPAN|CODE|BR|SMALL|ABBR)$/;
  function norm(s) { return String(s).replace(/\s+/g, ' ').trim(); }
  function own(el) { var parts = [], nodes = []; for (var c = el.firstChild; c; c = c.nextSibling) { if (c.nodeType === 3 || (c.nodeType === 1 && INLINE.test(c.nodeName))) { parts.push(c.textContent); nodes.push(c); } } return { text: norm(parts.join('')), nodes: nodes }; }
  function blocks(root) {
    if (!root || root.nodeType !== 1) return;
    var els = [root].concat([].slice.call(root.querySelectorAll('div,p,li,small,span,td')));
    for (var i = 0; i < els.length; i++) {
      var el = els[i]; if (el.getAttribute && el.getAttribute('data-ar-done')) continue;
      var o = own(el); if (o.text.length < 80 || !Object.prototype.hasOwnProperty.call(B, o.text)) continue;
      var span = document.createElement('span'); span.innerHTML = B[o.text];   // fixed Arabic from this file, never data
      el.insertBefore(span, o.nodes[0]); o.nodes.forEach(function (n) { el.removeChild(n); }); el.setAttribute('data-ar-done', '1');
    }
  }
  window.zybLang.extend({ terms: T, patterns: P });
