    try { new MutationObserver(function (ms) { for (var i = 0; i < ms.length; i++) for (var j = 0; j < ms[i].addedNodes.length; j++) blocks(ms[i].addedNodes[j].nodeType === 1 ? ms[i].addedNodes[j] : ms[i].addedNodes[j].parentNode); }).observe(document.body, { childList: true, subtree: true }); }
    catch (e) { /* old browser: the first pass is still done */ }
